struct task_struct {
	volatile long state;
	void *stack;
	atomic_t usage;
	unsigned int flags;

struct files_struct {
	atomic_t count;
	struct fdtable *fdt;
	struct fdtable fdtab;

struct file {
	union {
		struct list_head	fu_list;
		struct rcu_head 	fu_rcuhead;
	} f_u;
	struct path		f_path;

struct inode {
	umode_t			i_mode;
	unsigned short		i_opflags;
	uid_t			i_uid;
	gid_t			i_gid;

struct address_space {
	struct inode		*host;
	struct radix_tree_root	page_tree;
	spinlock_t		tree_lock;

struct dentry {
	atomic_t d_count;
	unsigned int d_flags;
	spinlock_t d_lock;
	int d_mounted;
	struct inode *d_inode;

struct path {
	struct vfsmount *mnt;
	struct dentry *dentry;
};
